def main():
    texts = {s['text'] for s in json.loads((ROOT / 'data/card-sleeves.json').read_text(encoding='utf8'))['sleeves']}
    patterns = ('Win a duel while you control ', 'Win runs with ')
    missing = [t for t in texts if t not in TERMS and not t.startswith(patterns)]
    assert not missing, missing
    for n, lang in enumerate(LANGS):
        names = json.loads((ROOT / 'data/i18n/cards' / f'{lang}.json').read_text(encoding='utf8'))
        card = {key: names[str(code)][0] for key, code in CARDS.items()}
        path = ROOT / 'data/i18n/ui' / f'{lang}.json'
        data = json.loads(path.read_text(encoding='utf8'))
        added = 0
        for key, values in TERMS.items():
            if key not in data:
                text = values[n]
                for name, value in card.items():
                    text = text.replace('{' + name + '}', value)
                data[key] = text
                added += 1
        path.write_text(json.dumps(data, ensure_ascii=False, indent=1) + '\n', encoding='utf8')
        print(lang, added)


if __name__ == '__main__':
    main()
